     TF("A nucleated settlement is one where houses are scattered widely.", False, "That is a dispersed pattern; nucleated means grouped together."),
     NUM("Birth rate 32 per 1 000, death rate 12 per 1 000. What is the natural increase per 1 000?", 20, "32 − 12 = 20.", tier="approfondissement"),
     MATCH("Match each pattern with its description.", [("Nucleated", "Houses grouped around a centre"), ("Dispersed", "Scattered farms"), ("Linear", "Houses along a road")], "These are the three settlement patterns.", tier="approfondissement"),
